    void solve() {
        long n = nl();
        long answer = 0;
        MeisselLehmer2 ml = new MeisselLehmer2(n / 2);
        for (int i = 0; i < primes.length; i++) {
            long delta = ml.pi(n / primes[i]) - (i + 1);
            if (delta <= 0) break;
            answer += delta;
