        private static class LongHashMap {
            public long[] keys;
            public long[] values;
            private int size = 0;
            private int capacity = 4;
            private static final long NG = Long.MIN_VALUE;

            public LongHashMap() {
                keys = new long[capacity];
                values = new long[capacity];
                Arrays.fill(keys, NG);
            }

            public boolean containsKey(long key) {
                int pos = hash(key) & (capacity - 1);
                while (keys[pos] != NG) {
                    if (keys[pos] == key) return true;
                    pos = (pos + 1) & (capacity - 1);
                }
                return false;
            }

            public long get(long key) {
                int pos = hash(key) & (capacity - 1);
                while (keys[pos] != NG) {
                    if (keys[pos] == key) return values[pos];
                    pos = (pos + 1) & (capacity - 1);
                }
                return NG;
            }

            public void put(long key, long value) {
                int pos = hash(key) & (capacity - 1);
                while (keys[pos] != NG) {
                    if (keys[pos] == key) {
                        values[pos] = value;
                        return;
                    }
                    pos = (pos + 1) & (capacity - 1);
                }
                if (size == capacity) resize();
                keys[pos] = key;
                values[pos] = value;
                size++;
            }

            private void resize() {
                capacity <<= 1;
                long[] newKeys = new long[capacity];
                long[] newValues = new long[capacity];
                Arrays.fill(newKeys, NG);
                for (int i = 0; i < keys.length; i++) {
                    if (keys[i] != NG) {
                        int pos = hash(keys[i]) & (capacity - 1);
                        while (newKeys[pos] != NG) pos = (pos + 1) & (capacity - 1);
                        newKeys[pos] = keys[i];
                        newValues[pos] = values[i];
                    }
