            private int hash(long x) {
                x ^= x >>> 33;
                x *= 0xff51afd7ed558ccdL;
                x ^= x >>> 33;
                x *= 0xc4ceb9fe1a85ec53L;
                x ^= x >>> 33;
                return (int) x;
